import React, {useEffect, useMemo} from "react";
import CoreButton from "../../../ui/buttons/coreButton";
import {useNavigate, useParams} from "react-router-dom";
import {toast} from "react-toastify";
import QueryError from "../../shared/QueryError";
import Loader from "../../../ui/loader/loader";
import {getApiErrorMessage} from "../../../api/errors";
import CoreTextField from "../../../ui/textFields/coreTextField";
import {useForm} from "react-hook-form";
import {yupResolver} from "@hookform/resolvers/yup";
import {statusSchema} from "./statusSchema";
import {ICreateStatus, IStatus} from "../../../models/status";
import {
    FormSurface,
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
} from "../../../ui/commonStyled/commonStyled";
import {useCreateStatusMutation, useEditStatusMutation, useGetStatusByIdQuery} from "./statusesApi";
import {useTranslation} from "../../../i18n";

interface IFormInput {
    name: string
}

const CreateOrEditStatus = () => {
    const {id} = useParams<{ id: string }>();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const validationSchema = useMemo(() => statusSchema(t), [t]);
    const {reset, register, handleSubmit, formState: {errors}} = useForm<IFormInput>({
        resolver: yupResolver(validationSchema),
    });

    const {data: status, isLoading, isError, error, refetch} = useGetStatusByIdQuery(id!, {skip: !id});
    const [createStatus, {isLoading: isCreatingStatus}] = useCreateStatusMutation();
    const [editStatus, {isLoading: isEditingStatus}] = useEditStatusMutation();
    const isSaving = isCreatingStatus || isEditingStatus;

    useEffect(() => {
        reset(status);
    }, [status, reset]);

    const onSubmit = async (data: IFormInput) => {
        const status: ICreateStatus = {
            name: data.name,
        };

        try {
            if (id) {
                const editStatusObject: IStatus = {...status, id, isSystem: false};
                await editStatus(editStatusObject).unwrap();
                toast.success(t("Status was changed"));
            } else {
                await createStatus(status).unwrap();
                toast.success(t("Status was created"));
            }

            navigate("/statuses", {replace: true});
        } catch (error) {
            toast.error(getApiErrorMessage(error, t("Status was not saved")));
        }
    };

    if (isLoading) {
        return <Loader/>;
    }

    if (id && (isError || !status)) return <MainDiv><QueryError error={error} onRetry={refetch}/></MainDiv>;

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{id ? t("Редактирование статуса") : t("Новый статус")}</PageTitle>
                    <PageSubtitle>{t("Название этапа, который будет использоваться в заказах.")}</PageSubtitle>
                </PageTitleGroup>
            </PageHeader>

            <FormSurface onSubmit={handleSubmit(onSubmit)}>
                <CoreTextField
                    label={t("Название")}
                    register={register}
                    name="name"
                    error={errors.name?.message}
                />
                <CoreButton
                    fullWidth
                    text={isSaving ? t("Saving...") : t("Сохранить")}
                    muiType="success"
                    type="submit"
                    disabled={isSaving}
                />
            </FormSurface>
        </MainDiv>
    );
};

export default CreateOrEditStatus;
